import type { SidebarsConfig } from '@docusaurus/plugin-content-docs'

// Doc items are checked at build time: a sidebar entry for a page that does not
// exist fails the build instead of rendering a dead link. Doc ids are paths
// under docs/ without the extension (docs/wiki/status.md → 'wiki/status').
//
// The two manual groups are autogenerated from the synced docs/ tree, so a new
// feature guide can never be built but missing from the sidebar. The corpus
// pages are listed by hand, because their order and labels are curated.
const sidebars: SidebarsConfig = {
  docs: [
    {
      type: 'category',
      label: 'Start here',
      collapsible: false,
      items: [
        { type: 'doc', id: 'index', label: 'What just-a-bot is' },
        { type: 'doc', id: 'wiki/overview', label: 'Overview' },
        { type: 'doc', id: 'wiki/architecture', label: 'Architecture' },
        { type: 'doc', id: 'manual/discord/setup', label: 'Setup' },
      ],
    },
    {
      type: 'category',
      label: 'Manual — the commands',
      collapsible: false,
      items: [{ type: 'autogenerated', dirName: 'manual/discord' }],
    },
    {
      type: 'category',
      label: 'Manual — common',
      collapsible: false,
      items: [{ type: 'autogenerated', dirName: 'manual/common' }],
    },
    {
      type: 'category',
      label: 'Maintainer — from the corpus',
      collapsible: false,
      items: [
        { type: 'doc', id: 'wiki/decisions', label: 'Decisions' },
        { type: 'doc', id: 'wiki/decisions-removals', label: 'Decisions — removals' },
        { type: 'doc', id: 'wiki/glossary', label: 'Glossary' },
        { type: 'doc', id: 'wiki/jukebox', label: 'Jukebox' },
        { type: 'doc', id: 'wiki/code-graph', label: 'The code graph' },
        { type: 'doc', id: 'wiki/open-questions', label: 'Open questions' },
      ],
    },
    {
      type: 'category',
      label: 'Reference and state',
      collapsible: false,
      items: [
        // Generated HTML in static/, not a Docusaurus route: `pathname://` makes
        // it a plain link (new tab, baseUrl still applied) instead of a router
        // navigation that would 404.
        { type: 'link', label: '@bots/shared (TypeDoc) ↗', href: 'pathname:///reference/' },
        { type: 'doc', id: 'wiki/status', label: 'Status' },
        { type: 'doc', id: 'wiki/log', label: 'Change log' },
      ],
    },
  ],
}

export default sidebars
